from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from fastapi.exceptions import HTTPException

app = FastAPI()

@app.exception_handler(HTTPException)
async def http_handler(req: Request, exc: HTTPException):
    return JSONResponse({'error': exc.detail, 'code': exc.status_code}, status_code=exc.status_code)

@app.exception_handler(Exception)
async def unhandled_handler(req: Request, exc: Exception):
    return JSONResponse({'error': 'internal error', 'code': 'INTERNAL'}, status_code=500)
